const publishDraft = `-- name: PublishDraft :one
UPDATE perspectives
SET arc_id = $1::uuid,
    place_id = $2::uuid,
    local_date = $3::date,
    hour = $4::smallint,
    title_if_new_arc = NULL,
    genre = $5::text,
    status = $6::text,
    lore_status = $7::text,
    published_at = now(),
    updated_at = now()
WHERE id = $8::uuid
RETURNING published_at
`

type PublishDraftParams struct {
	ArcID      uuid.UUID
	PlaceID    uuid.UUID
	LocalDate  pgtype.Date
	Hour       *int16
	Genre      string
	Status     string
	LoreStatus string
	ID         uuid.UUID
}

// Turns a draft into a published perspective in arc_id. The draft's title is
// cleared: the arc holds the title from here on.
func (q *Queries) PublishDraft(ctx context.Context, arg PublishDraftParams) (*time.Time, error) {
	row := q.db.QueryRow(ctx, publishDraft,
		arg.ArcID,
		arg.PlaceID,
		arg.LocalDate,
		arg.Hour,
		arg.Genre,
		arg.Status,
		arg.LoreStatus,
		arg.ID,
	)
	var published_at *time.Time
	err := row.Scan(&published_at)
	return published_at, err
}

const reactCountsOf = `-- name: ReactCountsOf :many
SELECT r.perspective_id, r.emoji, count(*)::int AS total,
       COALESCE(bool_or(r.user_id = $1::uuid), false)::boolean AS mine
FROM reacts r
WHERE r.perspective_id = ANY($2::uuid[])
GROUP BY r.perspective_id, r.emoji
ORDER BY r.perspective_id, r.emoji
`

type ReactCountsOfParams struct {
	Viewer *uuid.UUID
	Ids    []uuid.UUID
}

type ReactCountsOfRow struct {
	PerspectiveID uuid.UUID
	Emoji         string
	Total         int32
	Mine          bool
}

func (q *Queries) ReactCountsOf(ctx context.Context, arg ReactCountsOfParams) ([]ReactCountsOfRow, error) {
	rows, err := q.db.Query(ctx, reactCountsOf, arg.Viewer, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ReactCountsOfRow
	for rows.Next() {
		var i ReactCountsOfRow
		if err := rows.Scan(
			&i.PerspectiveID,
			&i.Emoji,
			&i.Total,
			&i.Mine,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

